// ===================== Configuração =====================
// Nome ou UUID do dispositivo no agente ('' = todos os dispositivos)
const DISPOSITIVO = '';

// Mapeamento manual (opcional) caso a detecção automática não acerte.
// Chave = dataItemId ou name do data item.
//   grupo: 'acel' (acelerômetro), 'giro' (giroscópio) ou 'temp' (temperatura)
//   eixo : 'X', 'Y' ou 'Z' (não precisa para temperatura)
// Ex.: const MAPA = { 'mpu_a1': { grupo: 'acel', eixo: 'X' }, 't': { grupo: 'temp' } };
const MAPA = {};

const BACKFILL   = 300;   // na 1ª leitura, quantas sequências recentes carregar
const MAX_PONTOS = 600;   // máx. de pontos por série enviados ao gráfico por leitura
// ========================================================

flow.set('mtc_ocupado', 0);

const NOMES = { acel: 'Acelerômetro', giro: 'Giroscópio', temp: 'Temperatura' };
const hora = (ms) => new Date(ms).toLocaleTimeString('pt-BR');
const status = (texto, cor) => {
    node.status({ fill: cor || 'green', shape: 'dot', text: texto });
    return { topic: 'status', payload: texto };
};

// ---------- Validação da resposta ----------
const doc = msg.payload || {};
const raiz = doc.MTConnectStreams;
if (!raiz) {
    flow.set('mtc_proximo', null);          // recomeça a sincronização
    let det = 'resposta sem MTConnectStreams';
    try {
        const e = doc.MTConnectError.Errors[0].Error[0];
        det = (e.$ && e.$.errorCode ? e.$.errorCode + ': ' : '') + (e._ || '');
    } catch (err) { /* não é MTConnectError */ }
    return [null, null, null, null, null, status('⚠️ ' + det + ' — ressincronizando', 'yellow')];
}

const h = (raiz.Header && raiz.Header[0] && raiz.Header[0].$) || {};
const first = Number(h.firstSequence);
const last  = Number(h.lastSequence);
const next  = Number(h.nextSequence);

// 1ª leitura ou agente reiniciado (instanceId mudou): pula para as amostras recentes
if (flow.get('mtc_proximo') == null || h.instanceId !== flow.get('mtc_instancia')) {
    flow.set('mtc_instancia', h.instanceId);
    flow.set('mtc_proximo', Math.max(first, last - BACKFILL + 1));
    context.set('tabela', {});
    context.set('ultimos', {});
    return [null, null, null, null, null, status('🔄 Conectado ao agente (instância ' + h.instanceId + ') — sincronizando…', 'blue')];
}

// Se ficou muito para trás (sensor muito rápido), descarta o atraso
let atraso = false;
if (last - next > 5000) {
    flow.set('mtc_proximo', last - BACKFILL + 1);
    atraso = true;
} else {
    flow.set('mtc_proximo', next);
}

// ---------- Extrai todos os <Samples> ----------
const itens = [];
for (const streams of raiz.Streams || []) {
    for (const ds of (streams && streams.DeviceStream) || []) {
        const dev = ds.$ || {};
        if (DISPOSITIVO && dev.name !== DISPOSITIVO && dev.uuid !== DISPOSITIVO) continue;
        for (const cs of ds.ComponentStream || []) {
            const comp = cs.$ || {};
            for (const amostras of cs.Samples || []) {
                if (!amostras || typeof amostras !== 'object') continue;
                for (const tag of Object.keys(amostras)) {
                    if (tag === '$') continue;
                    for (const el of amostras[tag]) {
                        const a = (el && el.$) || {};
                        itens.push({
                            tag: tag.replace(/^.*:/, ''),          // remove prefixo de namespace
                            id: a.dataItemId,
                            nome: a.name,
                            comp: comp.name || comp.component || '',
                            t: Date.parse(a.timestamp),
                            seq: Number(a.sequence),
                            taxa: Number(a.sampleRate),
                            bruto: String(typeof el === 'string' ? el : (el && el._ !== undefined ? el._ : '')).trim()
                        });
                    }
                }
            }
        }
    }
}
itens.sort((a, b) => a.seq - b.seq);

// ---------- Classificação: acelerômetro / giroscópio / temperatura + eixo ----------
function grupoDe(it) {
    const k = String(it.nome || it.id || '').toLowerCase();
    const t = it.tag.replace(/TimeSeries$/, '').toLowerCase();
    if (/gyr|giro/.test(k)) return 'giro';
    if (/temp/.test(k)) return 'temp';
    if (t === 'angularvelocity' || t === 'angularacceleration') return 'giro';
    if (t === 'acceleration') return 'acel';
    if (t === 'temperature') return 'temp';
    if (/acc|acel/.test(k) || /^a[_-]?[xyz]$/.test(k)) return 'acel';
    if (/^g[_-]?[xyz]$|angular|rot/.test(k)) return 'giro';
    return null;
}
function eixoDe(it) {
    for (const s of [it.nome, it.id, it.comp]) {
        if (!s) continue;
        const m = s.match(/([xyz])[^a-z]*$/i) || s.match(/^([xyz])(?:[^a-z]|$)/i) || s.match(/[^a-z]([xyz])[^a-z]/i);
        if (m) return m[1].toUpperCase();
    }
    return null;
}

const pontos = [];                                   // { grupo, serie, t, v }
const tabela = context.get('tabela') || {};
for (const it of itens) {
    const chave = it.nome || it.id;
    const mapa = MAPA[it.id] || MAPA[it.nome] || {};
    const grupo = mapa.grupo || grupoDe(it);
    const eixo = mapa.eixo || (grupo === 'temp' ? null : eixoDe(it));

    tabela[it.id || chave] = {
        'Data item': chave,
        'ID': it.id,
        'Tipo': it.tag,
        'Componente': it.comp,
        'Detectado como': grupo ? NOMES[grupo] + (eixo ? ' ' + eixo : '') : '—',
        'Valor': it.bruto.length > 40 ? it.bruto.slice(0, 40) + '…' : it.bruto,
        'Horário': isNaN(it.t) ? '' : hora(it.t)
    };

    if (!grupo || it.bruto === '' || it.bruto === 'UNAVAILABLE' || isNaN(it.t)) continue;
    const nums = it.bruto.split(/\s+/).map(Number);
    if (nums.some(isNaN)) continue;

    if (/TimeSeries$/.test(it.tag) && nums.length > 1) {
        // TIME_SERIES: N valores, o último no timestamp, espaçados por 1/sampleRate
        const dt = it.taxa > 0 ? 1000 / it.taxa : 0;
        nums.forEach((v, i) => pontos.push({ grupo, serie: eixo || chave, t: it.t - (nums.length - 1 - i) * dt, v }));
    } else if (nums.length === 3 && grupo !== 'temp' && !eixo) {
        // vetor "x y z" em um único data item
        ['X', 'Y', 'Z'].forEach((e, i) => pontos.push({ grupo, serie: e, t: it.t, v: nums[i] }));
    } else {
        pontos.push({ grupo, serie: grupo === 'temp' ? chave : (eixo || chave), t: it.t, v: nums[0] });
    }
}
context.set('tabela', tabela);

// Corrige diferença de relógio/fuso entre o agente e o Node-RED (gráficos usam a hora local)
let desvio = context.get('desvio');
if (pontos.length) {
    const recente = pontos.reduce((m, p) => Math.max(m, p.t), -Infinity);
    const d = Date.now() - recente;
    if (desvio == null || Math.abs(d - desvio) > 5000) desvio = d;
    context.set('desvio', desvio);
}
const ajuste = desvio != null && Math.abs(desvio) > 10000 ? desvio : 0;

// ---------- Saídas dos gráficos: uma mensagem por série (msg.topic = série) ----------
function msgsGrafico(grupo, casas) {
    const series = {};
    for (const p of pontos) {
        if (p.grupo !== grupo) continue;
        (series[p.serie] = series[p.serie] || []).push({ x: Math.round(p.t + ajuste), y: Number(p.v.toFixed(casas)) });
    }
    return Object.keys(series).sort().map(s => ({ topic: s, payload: series[s].slice(-MAX_PONTOS) }));
}

// ---------- Valores atuais (+ inclinação calculada pelo acelerômetro) ----------
const ultimos = context.get('ultimos') || {};
for (const p of pontos) {
    const k = p.grupo === 'temp' ? 'temp' : p.grupo + '_' + p.serie;
    if (!ultimos[k] || p.t >= ultimos[k].t) ultimos[k] = { t: p.t, v: p.v };
}
context.set('ultimos', ultimos);

const valores = [];
const casasDe = (k) => (k === 'temp' ? 1 : 3);
for (const k of ['acel_X', 'acel_Y', 'acel_Z', 'giro_X', 'giro_Y', 'giro_Z', 'temp']) {
    if (ultimos[k]) valores.push({ topic: k, payload: Number(ultimos[k].v.toFixed(casasDe(k))) });
}
if (ultimos.acel_X && ultimos.acel_Y && ultimos.acel_Z) {
    // independe da unidade (g, m/s², mm/s²)
    const ax = ultimos.acel_X.v, ay = ultimos.acel_Y.v, az = ultimos.acel_Z.v;
    const graus = 180 / Math.PI;
    valores.push({ topic: 'roll',  payload: Number((Math.atan2(ay, az) * graus).toFixed(1)) });
    valores.push({ topic: 'pitch', payload: Number((Math.atan2(-ax, Math.hypot(ay, az)) * graus).toFixed(1)) });
}

// ---------- Tabela e status ----------
const linhas = Object.values(tabela).sort((a, b) => String(a['Data item']).localeCompare(String(b['Data item'])));
const msgTabela = itens.length ? { payload: linhas } : null;

let texto, cor = 'green';
const reconhecidos = Object.values(tabela).filter(l => l['Detectado como'] !== '—').length;
if (Object.keys(tabela).length && !reconhecidos) {
    texto = '⚠️ Nenhum data item reconhecido como MPU6050 — confira a tabela e ajuste MAPA no nó "Interpreta /sample"';
    cor = 'yellow';
} else {
    texto = '✅ Conectado · ' + itens.length + ' amostras novas · sequência ' + (next - 1) + ' · ' + hora(Date.now())
        + (atraso ? ' · ⚠️ leitura atrasada, parte do buffer foi pulada' : '');
}

return [
    msgsGrafico('acel', 3),
    msgsGrafico('giro', 3),
    msgsGrafico('temp', 2),
    valores,
    msgTabela,
    status(texto, cor)
];

// Trata falhas de comunicação (sem conexão, timeout, HTTP != 200) e erros de parsing
flow.set('mtc_ocupado', 0);
let texto;

if (msg.error) {
    // vindo do nó catch (XML inválido, erro no código etc.)
    texto = '❌ Erro ao interpretar a resposta: ' + msg.error.message;
} else if (typeof msg.statusCode === 'number') {
    // o agente respondeu, mas com erro (ex.: OUT_OF_RANGE quando o buffer foi sobrescrito)
    flow.set('mtc_proximo', null);       // recomeça a sincronização
    const m = String(msg.payload || '').match(/errorCode="([^"]+)"/);
    texto = '⚠️ Agente respondeu HTTP ' + msg.statusCode + (m ? ' (' + m[1] + ')' : '') + ' — ressincronizando';
} else {
    // sem resposta: agente desligado, porta errada, timeout…
    texto = '❌ Sem conexão com o agente MTConnect (' + (msg.statusCode || msg.payload || 'erro') + ')';
}

texto += ' · ' + new Date().toLocaleTimeString('pt-BR');
node.status({ fill: 'red', shape: 'ring', text: texto });
return { topic: 'status', payload: texto };
